// Package imagesearch defines the types and the interface of an image search
// against one registry: what to search (Query), where (Target) and what comes
// back (Image). It is pure Go, with no UI and no network code of its own; the
// adapters that talk to a registry implement Searcher elsewhere.
//
// Anonymous Docker Hub search is not covered here (see IS-02).
package imagesearch

import "context"

// Target describes the registry entry a search runs against.
type Target struct {
	EntryKey    string
	Alias       string
	RegistryURL string
	APIURL      string
	RepoPrefix  string
	// Username and Password are empty for an anonymous entry (D12).
	Username string
	Password string
}

// Query is a search request. Limit 0 means the adapter's default.
type Query struct {
	Text  string
	Limit int
}

// Image is one search result.
type Image struct {
	EntryKey string
	Name     string
	// Repo is the final repository path, with the prefix and the library/
	// namespace applied exactly once (D39).
	Repo        string
	Description string
	Stars       int
	// HasStars tells whether Stars is meaningful for this registry.
	HasStars bool
	Official bool
}

// Searcher searches one registry. partial is true when the result is cut short
// (limit, deadline or a page that failed) but still usable.
type Searcher interface {
	Search(ctx context.Context, t Target, q Query) (images []Image, partial bool, err error)
}

// SearcherFunc adapts a function to the Searcher interface.
type SearcherFunc func(ctx context.Context, t Target, q Query) ([]Image, bool, error)

// Search calls f.
func (f SearcherFunc) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
	return f(ctx, t, q)
}
package imagesearch

import (
	"errors"

	"github.com/anthnel/devdesk/internal/oci"
)

// Verdict is one registry's answer to a search. The zero value is not a
// verdict: it means no answer yet, and Classify never returns it.
type Verdict int

const (
	// VerdictOK means rows were found.
	VerdictOK Verdict = iota + 1
	// VerdictNoResult means the registry answered and nothing matches.
	VerdictNoResult
	// VerdictRefused means unsupported or refused.
	VerdictRefused
	// VerdictFailed means network, deadline, 5xx, 429 or unreadable body.
	VerdictFailed
)

// String is the verdict as shown to the user.
func (v Verdict) String() string {
	switch v {
	case VerdictOK:
		return "ok"
	case VerdictNoResult:
		return "no result"
	case VerdictRefused:
		return "unsupported or refused"
	case VerdictFailed:
		return "failed"
	}
	return "pending"
}

// Outcome is a verdict and its marks. Invariant: Partial is set only with ok
// or no result (a partial walk that found nothing is still "no result"), never
// with refused or failed.
type Outcome struct {
	Verdict Verdict
	Partial bool
	Skipped bool
}

// ErrQueryTooShort: the catalog was not walked, the query is too short.
var ErrQueryTooShort = errors.New("query too short to walk a catalog")

// ErrPrefixNotInCatalog: no catalog name carries the entry's prefix.
var ErrPrefixNotInCatalog = errors.New("no catalog name carries the entry's prefix")

// Classify turns a search answer (error, row count, partial flag) into one
// Outcome. An error always wins over n and partial. With no error, n == 0
// keeps the Partial mark: the verdict is "no result" and Partial is set when
// the walk was cut short.
func Classify(err error, n int, partial bool) Outcome {
	switch {
	case err == nil && n == 0:
		return Outcome{Verdict: VerdictNoResult, Partial: partial}
	case err == nil:
		return Outcome{Verdict: VerdictOK, Partial: partial}
	case errors.Is(err, ErrQueryTooShort):
		return Outcome{Verdict: VerdictNoResult, Skipped: true}
	case errors.Is(err, ErrUnsupported), errors.Is(err, ErrPrefixNotInCatalog):
		return Outcome{Verdict: VerdictRefused}
	}
	var se *oci.StatusError
	if errors.As(err, &se) && refusedStatus(se) {
		return Outcome{Verdict: VerdictRefused}
	}
	return Outcome{Verdict: VerdictFailed}
}

// refusedStatus tells a refusal from a failure: the registry refusing the
// request (401, 403, 404, 405) or the token endpoint refusing the credentials
// (401, 403). Any other status, 429 and 5xx included, is a failure.
func refusedStatus(se *oci.StatusError) bool {
	switch se.Code {
	case 401, 403:
		return true
	case 404, 405:
		return se.Source != oci.SourceToken
	}
	return false
}
package imagesearch

import (
	"context"
	"errors"
	"net/url"
	"strings"

	"github.com/anthnel/devdesk/internal/oci"
)

// ErrUnsupported: this registry has no search path yet (non-Hub until IS-03,
// dhi.io until IS-17).
var ErrUnsupported = errors.New("image search not supported on this registry")

// isDHI reports whether the registry's host is exactly dhi.io, ignoring
// scheme, port, path, case and a trailing dot. Userinfo is not the host.
func isDHI(registryURL string) bool {
	raw := strings.TrimSpace(registryURL)
	if !strings.Contains(raw, "://") {
		raw = "https://" + raw
	}
	u, err := url.Parse(raw)
	if err != nil {
		return false
	}
	return strings.EqualFold(strings.TrimSuffix(u.Hostname(), "."), "dhi.io")
}

// ByRegistry sends a Hub target (oci.IsDockerHub(t.RegistryURL)) to hub, any
// other to other; a nil searcher answers ErrUnsupported without any request.
// dhi.io has no documented catalog API: it is refused before any routing.
func ByRegistry(hub, other Searcher) Searcher {
	return SearcherFunc(func(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
		if isDHI(t.RegistryURL) {
			return nil, false, ErrUnsupported
		}
		s := other
		if oci.IsDockerHub(t.RegistryURL) {
			s = hub
		}
		if s == nil {
			return nil, false, ErrUnsupported
		}
		return s.Search(ctx, t, q)
	})
}
package imagesearch

import (
	"regexp"
	"strings"
)

// repoComponent is one path component of a repository name: lowercase
// alphanumerics joined by '.', '_', '__' or runs of '-' (OCI distribution spec).
var repoComponent = regexp.MustCompile(`^[a-z0-9]+(?:(?:[._]|__|-+)[a-z0-9]+)*$`)

// validRepoPath reports whether every '/'-separated component of name is a
// valid OCI repository component. Empty is invalid.
func validRepoPath(name string) bool {
	if name == "" {
		return false
	}
	for _, p := range strings.Split(name, "/") {
		if !repoComponent.MatchString(p) {
			return false
		}
	}
	return true
}

// The ranks of MatchTier, lowest first.
const (
	TierExact      = iota // the name is the query
	TierLastEquals        // the last path segment is the query
	TierLastPrefix        // the last path segment starts with the query
	TierContains          // the name contains the query
	TierNoMatch           // nothing in the name matches
)

// MatchTier ranks name against query, lowest first, case-insensitive.
func MatchTier(query, name string) int {
	q, n := strings.ToLower(query), strings.ToLower(name)
	last := n[strings.LastIndex(n, "/")+1:]
	switch {
	case n == q:
		return TierExact
	case last == q:
		return TierLastEquals
	case strings.HasPrefix(last, q):
		return TierLastPrefix
	case strings.Contains(n, q):
		return TierContains
	}
	return TierNoMatch
}
