	hub := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		hubReqs.Add(1)
		_, _ = fmt.Fprint(w, `{"results":[]}`)
	}))
	t.Cleanup(hub.Close)
