		_, _, _ = catalogOutcome(t, s, Target{RegistryURL: "docker.io"}, "n")
		if hubReqs.Load() != 1 || catReqs.Load() != 0 {
			t.Errorf("requests hub=%d catalog=%d, want 1 0", hubReqs.Load(), catReqs.Load())
		}
	})
}
